def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frames = []

    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)

        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if (all(grid[r0][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r1][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r][c0] == color for r in range(r0, r1 + 1)) and
            all(grid[r][c1] == color for r in range(r0, r1 + 1))):
            frames.append((color, r0, r1, c0, c1))

    source = None
    for frame in frames:
        color, r0, r1, c0, c1 = frame
        if any(grid[r][c] == color
               for r in range(r0 + 1, r1)
               for c in range(c0 + 1, c1)):
            source = frame
            break

    if source is None:
        return out

    scolor, sr0, sr1, sc0, sc1 = source
    pattern = [
        [grid[r][c] == scolor for c in range(sc0 + 1, sc1)]
        for r in range(sr0 + 1, sr1)
    ]
    sh, sw = len(pattern), len(pattern[0])

    # Remove the framed objects; redraw the source and matching frames.
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = 0

    for color, r0, r1, c0, c1 in frames:
        if (color, r0, r1, c0, c1) == source:
            target_pattern = pattern
        elif r1 - r0 - 1 == sh and c1 - c0 - 1 == sw:
            target_pattern = pattern
        else:
            continue

        for c in range(c0, c1 + 1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = color
            out[r][c1] = color
        for i in range(sh):
            for j in range(sw):
                if target_pattern[i][j]:
                    out[r0 + 1 + i][c0 + 1 + j] = color

    return out
